{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Substance Use Disorder (SUD) is a significant and escalating contributor to the global burden of disease... Despite growing scholarly and clinical attention, the quality of and access to treatment remain markedly uneven... lack of consensus on standardized international indicators... diversity of treatment approaches... deficiency of robust evidence on the long-term impact",
      "reason": "The current state of knowledge (SUD burden, uneven treatment quality) and important uncertainties (lack of consensus, diversity of approaches, evidence gaps) are clearly described in the Introduction section."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Consequently, the implementation of localized policies and targeted, evidence-based interventions is urgently required to address these systemic inequities... This systematic review... aims to address these gaps",
      "reason": "The importance and need for conducting the review are explained by highlighting the urgency of addressing systemic inequities and the necessity to address specific knowledge gaps identified in existing research."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_6",
      "quote": null,
      "reason": "The text refers to 'previous studies' (primary research) rather than 'previous systematic reviews'. No prior systematic review is cited to update or replicate, so the condition 'When similar systematic reviews exist' does not apply."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": "text_6",
      "quote": null,
      "reason": "The review focuses on intervention effectiveness and indicators, but does not describe the proposed mechanism of action of the interventions (e.g., pharmacological or psychological mechanisms) in the rationale."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": "text_6",
      "quote": null,
      "reason": "The text discusses moderating factors and PICO/PRISMA frameworks but does not mention or consider a logic model to show hypothesised relationships between intervention components and outcomes."
    }
  ],
  "confidence": 90
}

{
